/*
 * A284035  Upper twin primes which correspond to the hypotenuse in a
 *          Pythagorean triple whose short leg is also a prime.
 * https://oeis.org/A284035
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (p^2 + 1)/2, where p is the short‑leg prime of a
 *            primitive Pythagorean triple that makes (p^2+1)/2 a prime and
 *            (p^2+1)/2 – 2 a prime. The sequence is generated by testing
 *            successive prime p
 * Range:     u8 n <= 4, u16 n <= 7, u32 n <= 8, u64 n <= 35, u128 n <= 35,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"

#define SIEVE_LIMIT 20000000   /* upper bound for precomputed primes */
#define PRIME_CAP   1300000    /* enough for primes <= SIEVE_LIMIT */

static uint32_t primes[PRIME_CAP];
static size_t   prime_count = 0;
static bool     primes_built = false;

static void build_primes(void)
{
    if (primes_built) return;

    uint8_t *is_prime = (uint8_t*)malloc(SIEVE_LIMIT + 1);
    if (!is_prime) return;  /* allocation failed – fallback will search by trial */

    memset(is_prime, 1, SIEVE_LIMIT + 1);
    is_prime[0] = is_prime[1] = 0;

    for (uint32_t i = 2; (uint64_t)i * i <= SIEVE_LIMIT; ++i) {
        if (is_prime[i]) {
            for (uint32_t j = i * i; j <= SIEVE_LIMIT; j += i)
                is_prime[j] = 0;
        }
    }

    for (uint32_t i = 2; i <= SIEVE_LIMIT; ++i) {
        if (is_prime[i]) {
            if (prime_count < PRIME_CAP)
                primes[prime_count++] = i;
        }
    }

    free(is_prime);
    primes_built = true;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined for n < 1, return 0 */

    build_primes();

    size_t cnt = 0;

    /* Search within primes precomputed up to SIEVE_LIMIT */
    for (size_t i = 0; i < prime_count; ++i) {
        uint32_t p = primes[i];
        if (p < 3) continue;  /* skip 2 – odd primes only */

        unsigned __int128 tmp = (unsigned __int128)p * (unsigned __int128)p + 1;
        seq_t q = (seq_t)(tmp / 2);

        if (is_prime_big(q) && is_prime_big(q - 2)) {
            ++cnt;
            if (cnt == n) return q;
        }
    }

    /* If n is larger than what the sieve covers, continue searching beyond it */
    uint32_t candidate = (prime_count > 0 ? primes[prime_count - 1] + 2 : 3);
    if ((candidate & 1) == 0) ++candidate;  /* make odd */

    for (;;) {
        if (is_prime_big(candidate)) {
            unsigned __int128 tmp = (unsigned __int128)candidate * (unsigned __int128)candidate + 1;
            seq_t q = (seq_t)(tmp / 2);
            if (is_prime_big(q) && is_prime_big(q - 2)) {
                ++cnt;
                if (cnt == n) return q;
            }
        }
        /* avoid infinite loop on overflow – though not expected for n <= ~10000 */
        if (candidate > 0xFFFFFFFEU) break;
        candidate += 2;
    }

    /* Should never reach here for valid inputs */
    return (seq_t)0;
}
